                        content = Text("Internal Server Error")
                        err = Response(code=500, content=content)
                        self._send_head(err)
                        self._send_body(err)
                    else:
                        self._send_head(response)
                        self._send_body(response)
        except Exception:
            logger.error("Internal Server Error", exc_info=True)

    def close(self):
        self._parser.close()

